from pathlib import Path
ROOT=Path(__file__).resolve().parents[2]
p=ROOT/'engine/vigile/web/index.html';s=p.read_text(encoding='utf8');s=s.replace('<script src="/assets/app.js" defer></script>','<script src="/assets/app.js" defer></script><script src="/assets/voice-controller.js" defer></script>')
voice='''<section class="voice-panel" aria-label="Interacción oral local"><h3>Voz offline · pulsar para hablar</h3><p>El audio se procesa en memoria y no se conserva. La transcripción requiere revisión; nunca modifica mediciones ni autoriza tratamientos.</p><label for="voice-language">Idioma de voz y respuesta</label><select id="voice-language"><option value="es">Español</option><option value="en">English</option></select><button id="voice-refresh" class="secondary" type="button">Comprobar STT / TTS</button><p id="voice-availability" role="status">Disponibilidad aún no comprobada.</p><button id="voice-record" type="button" aria-pressed="false">🎙 Hablar / terminar</button><button id="voice-cancel" type="button" class="secondary">Cancelar y descartar</button><p id="voice-state" role="status" aria-live="polite"></p><label for="voice-transcript">Transcripción editable · revisar antes de enviar</label><textarea id="voice-transcript" maxlength="1200" rows="3"></textarea><button id="voice-send" type="button" disabled>Enviar transcripción revisada</button><details open><summary>Texto validado exacto que se leerá</summary><p id="voice-approved"></p></details><label for="voice-rate">Velocidad de lectura</label><select id="voice-rate"><option value="-2">Más lenta</option><option value="0" selected>Normal</option><option value="2">Más rápida</option></select><button id="voice-play" type="button" disabled>▶ Reproducir respuesta validada</button><button id="voice-stop" type="button" class="secondary" disabled>■ Detener reproducción</button><p id="voice-timing" class="caption"></p></section>'''
anchor='<form id="chat-form">';assert anchor in s;s=s.replace(anchor,voice+anchor);p.write_text(s,encoding='utf8')
p=ROOT/'engine/vigile/web/app.js';s=p.read_text(encoding='utf8');s=s.replace('question,history:chatHistory.slice(-3)','question,language:document.getElementById("voice-language")?.value||"es",history:chatHistory.slice(-3)');s=s.replace("target.replaceChildren(el('p',answer.message,'caption'));","window.VigileVoice?.accept(answer);target.replaceChildren(el('p',answer.message,'caption'));",1);p.write_text(s,encoding='utf8')
